-- Field diagnostics: a join on Let someone in now writes a `nearby` session
-- record on both phones (review of 2026-11-24, item 14), which only rooms did
-- before, so a newcomer who came away short showed in the field only as a
-- complaint. The session record's `mode` gains `join`, and a session that
-- moved a starting copy says what of it: `granted` and `exchanged` (the
-- ordinary steps ran on the join's link after a whole copy, decision
-- 2026-11-24-the-join-link-runs-the-ordinary-exchange) and, when they did not,
-- why, as one count of `exchangeOlder` (the other phone's app is older),
-- `exchangeNoPieces` (the newcomer's own language did not open) and
-- `exchangeLeft` (the newcomer's person left first), `copyWhole`,
-- `copyFilled`, `copyDocsKept`, `copyDocsMissing`, `copyDocsRefused`,
-- `copyParts`, `copyNos`, and `copyNo`, the word for why a teammate gave no
-- more. Counts and fixed words only, as before: never who.
-- diag.ops_nearby counts sessions by how they ended and by link, which a join's
-- record joins with no change here.

-- The twin of DIAG_SCHEMA, NEARBY_DIAG_SCHEMA and DIAG_CONTEXT in
-- packages/sync/src/diagnostics.ts and nearbyDiag.ts; scripts/diagSchema.test.ts
-- holds them equal. Change both together.
create or replace function diag.schema() returns jsonb language sql immutable as $$
select
-- diag-schema:begin
'{"kinds":{"sync":{"n":["ms","pushNetMs","pullNetMs","applyMs","pushed","rejected","pulled","pages","pending","offlineMs","rejNotMember","rejNotAllowed","rejNotListed","rejInvalid","rejClockAhead","rejOther","requeued","more"],"t":{"outcome":["ok","offline","unrenewed","refused","too_old","error"],"error":"token","code":"token","phase":["push","pull","snapshot","checkpoint","load","store"]}},"load":{"n":["ms","events","fromSnapshot","staleCheckpointSeq","readMs","foldMs"],"t":{"reason":["open","rejected","requeue","redaction","snapshot","membership","other"],"checkpoint":["none","ok","old_reducer"]}},"checkpoint":{"n":["ms","kb","seq","pruned"],"t":{"path":["fast","slow"]}},"open":{"n":["ms","syncs","pulled","snapshotMs","loadMs"],"t":{"cold":["yes","no"]}},"snapshot":{"n":["ms","chunks","resumedChunks","bytes","seq"],"t":{"outcome":["ok","none","stale"],"why":["cold","redaction","reducer"]}},"fill":{"n":["ms","msToMap","headKb","passages","rows"],"t":{"event":["start","done","fallback","restart"],"why":["cold","redaction","reducer"],"reason":["no_rpc","no_cut","no_lines","old_lines","error","cut_gone"]}},"transfer":{"n":["count","bytes","ms","maxMs","signMs","fetchMs","verifyMs","failOffline","failHttp4xx","failHttp5xx","failHash","failDisk","failOther","failAuth","failNotFound","failTooLarge","failBadDigest","failGone"],"t":{"dir":["up","down"],"src":["lang","guide","handover","stream","source","help","study"]}},"device":{"n":["freeDiskMb","totalDiskMb","blobCacheMb","blobsWanted","lostFiles","lostRecordings","journalPending","journalFailed","uploadsWaiting","oldestUnsentMin","wantedStuckMin","streams","localEvents","dbMb","diagQueued","diagDropped"],"t":{}},"error":{"n":[],"t":{"name":"token","where":"token","errorId":"token","fatal":["yes","no"],"code":"token"}},"expected":{"n":["count"],"t":{"where":"token","name":"token","code":"token"}},"audio":{"n":["takes","takeMs","tooShort","micRefused","startFail","stopFail","saveFail","encodeFail","wavKept","interrupted","plays","playFail","playNotHere","streamFail","waits","waitMs","maxWaitMs","streamWaits","streamWaitMs","maxWaitLinkMs","maxWaitCopyMs","maxWaitLoadMs","maxWaitBusyMs","maxWaitStreamed"],"t":{}},"auth":{"n":["ms","status","attempt","ageH","pending","eventsLeft","uploadsLeft","accountLeft","sinceOkMs"],"t":{"op":["sign_in","sign_up","code","v2","redeem","join","renew","ended","courier","outbox","route","delete","org_list"],"outcome":["ok","offline","http","refused","rate_limited","server","expired","used","not_found","retired","needs_name","done","keep","gone","unreachable","retry","failed","home","no_org","org_unknown"],"code":"token","action":"token"}},"nearby":{"n":["ms","levelMs","heard","echoed","alone","maybe","taps","maxUnmatched","pipeFails","strangers","busy","noAnswer","sessions","done","fallbacks","events","sent","refused","overBudget","files","served","fileFails","keyRefused","farAhead","noRoom","cutBackups","older","clockOff","newerApp","openMin","scanMin","pauseMin","syncMin","viaDirect","greets","maxMeetMs","docsKept","docsRefused","docsMissing","docsCapped","libHeld","libTheirs","libGot","libServed","granted","exchanged","copyWhole","copyFilled","copyDocsKept","copyDocsMissing","copyDocsRefused","copyParts","copyNos","exchangeOlder","exchangeNoPieces","exchangeLeft"],"t":{"event":["room","session","find","blocked","deliver"],"mode":["screen","open","join"],"stop":["asked","idle","wait","run","level","no-key","rest"],"role":["i","r"],"end":["done","silent","no-answer","said","heard","dropped","stalled","failed"],"bye":["done","nothing","busy","protocol","identity","not-member","stopped"],"refusal":["window","revoked","org","expired","pass-expired","other"],"link":["wifi-direct","hotspot","awdl","bluetooth"],"code":["NOT_AVAILABLE","NO_PERMISSION","BLUETOOTH_OFF","WIFI_OFF","BAD_ARGUMENT","ADVERTISE_UNSUPPORTED","ADVERTISE_FAILED","SCAN_FAILED","FIND_NOT_RUNNING","PEER_GONE","PIPE_FAILED","PIPE_TIMEOUT","P2P_UNSUPPORTED","GROUP_BUSY","GROUP_FAILED","HOTSPOT_NO_CHANNEL","HOTSPOT_INCOMPATIBLE","HOTSPOT_TETHERING_DISALLOWED","HOTSPOT_FAILED","JOIN_FAILED","JOIN_TIMEOUT","HOST_TAKEN_DOWN","LINK_UNKNOWN","LINK_CLOSED","LINK_DROPPED","TAG_FAILED","FRAME_TOO_LARGE","MESSAGE_TOO_LARGE","NOT_SECURED","ALREADY_SECURED","OPENING_AFTER_SECURE","TRANSFER_BUSY","FILE_TOO_BIG","FILE_NO_SPACE","FILE_REFUSED","FILE_CANCELLED","FILE_UNREADABLE","FILE_WRITE_FAILED","FILE_SIZE_MISMATCH","STAGING_REFUSED","STOPPED","INTERNAL"],"error":"token","why":["not-in-build","android-too-old","no-bluetooth-le","no-wifi-direct","no-key","no-certificate","read-only","bluetooth-off","wifi-off","location-off","permission-approximate","permission-blocked"],"adv":["yes","no"],"direct":["yes","no"],"hotspot":["yes","no"],"copyNo":["versions","not-filled","not-allowed","not-here","malformed"]}}},"context":["installId","os","osVersion","model","appVersion","runtimeVersion","updateId","channel","embedded","reducerVersion","protocolVersion"]}'
-- diag-schema:end
::jsonb
$$;

-- Unchanged; restated so the newest migration holding the schema holds its
-- token pattern too (scripts/diagSchema.test.ts reads both from one file).
create or replace function diag.is_token(p text) returns boolean language sql immutable as $$
  select p is not null and p ~ '^[A-Za-z0-9 _.:()/#-]{1,80}$'
$$;
